import json,os
os.makedirs('/task/workspace/exporter',exist_ok=True)
open('/task/workspace/exporter/core.py','w').write('''import csv, io\n\ndef export_records(records, user, params):\n    params = params or {}\n    admin = user.get('role') == 'admin'\n    out = []\n    for r in sorted(records, key=lambda r: r['id']):\n        if not admin and r.get('project') not in user.get('projects', []):\n            continue\n        if r.get('confidential') and not (admin and params.get('purpose') == 'audit'):\n            continue\n        out.append(r)\n    buf = io.StringIO()\n    w = csv.writer(buf, lineterminator='\\n')\n    w.writerow(['id','title','owner','amount'])\n    for r in out:\n        w.writerow([r['id'], r['title'], r['owner'], r['amount']])\n    return buf.getvalue()\n''')
open('/task/workspace/exporter/__init__.py','w').write('from .core import export_records\n')
open('/task/workspace/reghelper.py','w').write('''import json, clm_jev\nP='/task/workspace/context.json'\ndef load(): return json.load(open(P))\ndef save(c): json.dump(c,open(P,'w'))\ndef affected(reg, new_items):\n    """reg: {id:text}; new_items: {id:text}. returns {newid:{regid:prob}}"""\n    res={}\n    for nid,nt in new_items.items():\n        r=clm_jev.judge('Does the new change notice item modify, replace or withdraw this existing requirement?', reg, background='New item: '+nt)\n        res[nid]=r.get('answers',{}) if r.get('status')=='ok' else {}\n    return res\ndef set_register(c, lines):\n    c['entries']=[e for e in c['entries'] if e['id']!='register']\n    c['entries'].insert(0,{'id':'register','role':'note','body':'\\n'.join(lines)})\n''')
